command -v python3>/dev/null||exit 127;python3 -c 'import json as j;from fractions import Fraction as F;P=(2,3,5,7,11,13);K=128;G=30030;V=lambda n,p:(lambda f:f(f,n,0))(lambda f,n,k:f(f,n//p,k+1)if n%p==0 else k);E=lambda a:__import__("math").prod((F(p)**(x+1)for p,x in zip(P,a)),start=F(1));D=lambda g:[V(g.numerator,p)-V(g.denominator,p)-1 for p in P];X=lambda a:sum((v+1)*p for p,v in zip(P,a));Z=lambda m:sum((F(1,k**m)if k%2 else-F(1,k**m))for k in range(1,K+1))/(1-F(2)**(1-m));a=[0]*6;R=[];S=set();n=0;exec("while tuple(a)not in S:\n S.add(tuple(a));g=E(a);x=X(a);m=2+x%38;y,z=Z(m),Z(m+1);q=((1000*abs(y).numerator)//abs(y).denominator%3,(1000*abs(z).numerator)//abs(z).denominator%3);r=g/F(G);p=1/r;R.append([n,a[:],[g.numerator,g.denominator],[p.numerator,p.denominator],\"0\"if r==1 else\"ln(%s/%s)\"%(r.numerator,r.denominator),q,D(g)==a]);a=[(a[0]+1+q[0])%4,(a[1]+a[5])%7,(a[2]+q[1])%3,a[3],a[4],-a[5]];n+=1");print(j.dumps({"model":"EXACT_GODEL_ZERO_INFORMATION_TM","seed":[0]*6,"G0":G,"formal_probability":"G0/G","surprisal":"ln(G/G0)","steps":n,"return_state":a,"zero_fixed_point":a==[0]*6,"exact":all(x[-1]for x in R),"levels":R},separators=(",",":")))'